  return points.slice().sort((a,b)=>String(b.publicationVersion||'').localeCompare(String(a.publicationVersion||''))||((b.status==='확정'?2:b.status==='잠정'?1:0)-(a.status==='확정'?2:a.status==='잠정'?1:0)))[0];
